<script setup>import {computed,onMounted,reactive,ref} from 'vue';import MEmptyState from '../../components/mds/MEmptyState.vue';import MMobileTopBar from '../../components/mds/MMobileTopBar.vue';import MSpinner from '../../components/mds/MSpinner.vue';import {HostSurface} from '../../platform/host-adapter.mjs';import {createAdminApi} from './domain/admin-api.mjs';import {adminAuditViewModel,adminUsersViewModel} from './domain/admin-view.mjs';import AdminAuditDesktop from './desktop/AdminAuditDesktop.vue';import AdminUsersDesktop from './desktop/AdminUsersDesktop.vue';import AdminAuditMobile from './mobile/AdminAuditMobile.vue';import AdminUsersMobile from './mobile/AdminUsersMobile.vue';const props=defineProps({surface:String,adapter:Object,hostUnavailable:Boolean});const emit=defineEmits(['back']);const api=createAdminApi();const isNative=computed(()=>props.surface===HostSurface.NATIVE);const safeArea=ref(props.adapter?.getSafeArea?.()||{});const safeAreaStyle=computed(()=>Object.fromEntries(['top','right','bottom','left'].flatMap((side)=>Number.isFinite(Number(safeArea.value?.[side]))?[[`--mds-mobile-safe-${side}`,`${Number(safeArea.value[side])}px`]]:[])));const state=reactive({phase:'loading',mode:'users',rows:[],auditRows:[],currentUser:null,error:null});const canViewAudit=computed(()=>state.currentUser?.role==='super_admin');async function load(){if(props.hostUnavailable){state.phase='error';state.error={status:503,message:'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.'};return;}state.phase='loading';try{const [users,session]=await Promise.all([api.getUsers(),api.getCurrentUser()]);state.rows=adminUsersViewModel(users).rows;state.currentUser=session?.user||null;state.mode='users';state.phase='ready';}catch(error){state.phase='error';state.error=error;}}async function openAudit(){if(!canViewAudit.value)return;state.phase='loading';try{state.auditRows=adminAuditViewModel(await api.getAudit()).rows;state.mode='audit';state.phase='ready';}catch(error){state.phase='error';state.error=error;}}function leaveAudit(){state.mode='users';}function back(){if(state.mode==='audit')return leaveAudit();if(isNative.value&&props.adapter)return props.adapter.goBack({reason:'admin-users'});emit('back');}onMounted(load);</script>
<template><div v-if="state.phase==='loading'" :class="isNative?'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]':'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'"><MSpinner :size="28"/></div><section v-else-if="state.phase==='error'" :class="isNative?'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]':'min-h-[360px] bg-[var(--mds-bg-page)]'"><MMobileTopBar v-if="isNative" title="Quản trị hệ thống" @back="back"/><MEmptyState :title="state.error.status===403?'Bạn không có quyền xem nhật ký audit':'Không thể mở quản trị hệ thống'" :description="state.error.message"/></section><AdminAuditMobile v-else-if="isNative&&state.mode==='audit'" :rows="state.auditRows" :safe-area-style="safeAreaStyle" @back="leaveAudit"/><AdminUsersMobile v-else-if="isNative" :rows="state.rows" :safe-area-style="safeAreaStyle" :can-view-audit="canViewAudit" @back="back" @audit="openAudit"/><AdminAuditDesktop v-else-if="state.mode==='audit'" :rows="state.auditRows" @back="leaveAudit"/><AdminUsersDesktop v-else :rows="state.rows" :can-view-audit="canViewAudit" @audit="openAudit"/></template>
